package com.fitconnect.payment.api; import com.fitconnect.payment.service.PaymentService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/payments") public class PaymentController {private final PaymentService s; public PaymentController(PaymentService s){this.s=s;} @PostMapping public ResponseEntity<PaymentResponse> pay(@Valid @RequestBody PaymentRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.pay(r));} @GetMapping("/booking/{id}") public PaymentResponse booking(@PathVariable Long id){return s.getByBooking(id);} @GetMapping("/user/{id}") public List<PaymentResponse> user(@PathVariable Long id){return s.byUser(id);} @PostMapping("/{id}/refund") public PaymentResponse refund(@PathVariable Long id){return s.refund(id);}}
